// PortalWidget Medic — Weekly Widget Health Scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0

(function() {
    try {
        var engine = new PwmEngine();
        var stats = engine.scanAllWidgets(true);
        gs.info('PortalWidget Medic weekly scan complete: ' + JSON.stringify(stats));
    } catch (e) {
        gs.error('PortalWidget Medic weekly scan failed: ' + e);
    }
})();
